def calc(expr: str) -> int | str:
    s = expr
    n = len(s)
    i = 0

    def skip() -> None:
        nonlocal i
        while i < n and s[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        q, r = divmod(a, b)
        if (a < 0) != (b < 0) and r != 0:
            return q + 1
        return q

    def parse_expr() -> int:
        left = parse_term()
        while True:
            skip()
            if i < n and s[i] in "+-":
                op = s[i]
                i += 1
                right = parse_term()
                left = left + right if op == "+" else left - right
            else:
                break
        return left

    def parse_term() -> int:
        left = parse_unary()
        while True:
            skip()
            if i < n and s[i] in "*/%":
                op = s[i]
                i += 1
                right = parse_unary()
                if op == "*":
                    left = left * right
                elif right == 0:
                    raise ZeroDivisionError
                elif op == "/":
                    left = trunc_div(left, right)
                else:
                    left = left - right * trunc_div(left, right)
            else:
                break
        return left

    def parse_unary() -> int:
        skip()
        if i < n and s[i] == "-":
            i += 1
            return -parse_unary()
        return parse_power()

    def parse_power() -> int:
        base = parse_primary()
        skip()
        if i < n and s[i] == "^":
            i += 1
            exp = parse_unary()
            if exp < 0:
                raise ValueError
            return base ** exp
        return base

    def parse_primary() -> int:
        skip()
        if s[i] == "(":
            i += 1
            val = parse_expr()
            skip()
            i += 1
            return val
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    try:
        return parse_expr()
    except (ZeroDivisionError, ValueError):
        return "error"
